create table if not exists payroll_runs (id uuid primary key default gen_random_uuid(), period_start date not null, period_end date not null, status text not null default 'Draft', approved_by uuid references users(id), approved_at timestamptz, released_at timestamptz, created_at timestamptz not null default now()); create table if not exists payroll_items (id uuid primary key default gen_random_uuid(), payroll_run_id uuid not null references payroll_runs(id), employee_id uuid not null references employees(id), daily_rate numeric(14,2) not null, days_worked numeric(8,2) not null default 0, gross_pay numeric(14,2) not null default 0, total_deductions numeric(14,2) not null default 0, net_pay numeric(14,2) not null default 0);
